  'Monitoring and limits': 'Monitoreo y límites',
  'Source checks use HTTP GET. Unchanged automatic runs skip the agent. An optional JSON pointer watches only that value and ignores object key order. Manual tests always run. Quiet hours defer successful Bot reports. Failures and approvals stay visible. Usage limits can overrun when reports arrive late.':
    'Las comprobaciones de origen utilizan HTTP GET. Las ejecuciones automáticas sin cambios omiten al agente. Un puntero JSON opcional observa solo ese valor e ignora el orden de las claves de los objetos. Las pruebas manuales siempre se ejecutan. Las horas de silencio posponen los informes exitosos del Bot. Los fracasos y las aprobaciones permanecen visibles. Los límites de uso pueden sobrepasarse cuando los informes llegan tarde.',
  'HH:mm': 'HH:mm',
