    'Mueva la conversación guardada completa, la lista de verificación, los archivos adjuntos y los archivos. Las sesiones y credenciales del proveedor permanecen aquí. El hilo de destino utiliza el arnés predeterminado de esa computadora, sin más acceso que el que tiene este hilo. Nada se ejecuta hasta que envías el siguiente mensaje allí. Puede cambiar su modelo después de que se abra. Este hilo permanece aquí, de solo lectura, para recuperación.',
  'Copy files and local Git history. The source project and chats stay here. A new folder is created on the destination. Worktrees use its configured worktree directory.':
    'Copie archivos y el historial de Git local. El proyecto fuente y los chats se quedan aquí. Se crea una nueva carpeta en el destino. Los árboles de trabajo utilizan su directorio de árbol de trabajo configurado.',
