  'Enable agent computer use on this computer':
    'Habilitar el uso de la computadora del agente en esta computadora',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Otorga a los agentes grabables acceso al escritorio de esta computadora. Se excluyen los agentes de solo lectura. El usuario y los agentes comparten el estado del escritorio y de la aplicación.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Deje Cua Driver vacío para detectarlo en la RUTA de esta computadora o en su carpeta de instalación estándar. Los cambios se aplican a los turnos de nuevos agentes.',
  '1. Install on this computer': '1. Instalar en esta computadora',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Ejecute el instalador oficial en el host de ejecución y luego actualice el estado. Descarga e instala CuaDriver; no se requiere ninguna cuenta Cua.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Los sistemas Linux mínimos necesitan libxi6 y at-spi2-core. GNOME necesita el asistente WinRects incluido en Cua; consulte la guía de instalación.',
  'Install and set up Cua Driver': 'Instalar y configurar el controlador Cua',
  'Detect / check Cua Driver': 'Detectar/comprobar el controlador Cua',
  '2. Permissions & desktop access': '2. Permisos y acceso al escritorio',
