  'Dovo Connect: {value0}': 'Conexión Dovo: {value0}',
  'Pair again': 'Emparejar de nuevo',
  'Connection stages': 'Etapas de conexión',
  'Start your computer': 'Inicia tu computadora',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Abra Dovo en su computadora y manténgalo activo. En Configuración → Dispositivos y tiempo de ejecución, inicie sesión y habilite Dovo Connect. Inicie sesión en la misma cuenta en su teléfono y elija Conectar. No se necesita ningún código de emparejamiento, VPN o IP local para acceder a Internet.',
  'Direct internet connection': 'Conexión directa a Internet',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN conecta su teléfono directamente a la computadora. Su contenido está cifrado de extremo a extremo. Habilitar Dovo Connect permite un respaldo de retransmisión cifrada si una red bloquea las conexiones directas. El relé reenvía tráfico cifrado; no puede leer su contenido.',
  'LAN / VPN connections': 'Conexiones LAN/VPN',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Empareje LAN/VPN por separado para preferir esa conexión cuando esté disponible. Copie la dirección Wi-Fi, Tailscale, NetBird o HTTPS completa que se muestra en su computadora, incluido su puerto. localhost y 0.0.0.0 no son direcciones a las que se pueda conectar su teléfono.',
  'Check your network': 'Comprueba tu red',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Utilice el mismo Wi-Fi o conecte ambos dispositivos a su VPN. Para conexiones Wi-Fi, permita que Dovo acceda a su red local en la configuración del iPhone.',
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Los códigos de emparejamiento caducan después de dos minutos. Los códigos CLI se aprueban automáticamente; Es posible que un código del escritorio necesite aprobación allí.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Tu emparejamiento está guardado. Intente Reconectar antes de generar otro código. Si la dirección cambió, elija Actualizar dirección de conexión en la configuración de esta computadora.',
