  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Ejecuta el agente de cada conversación nueva, sus comandos y sus terminales en un contenedor local de Docker o Podman. Solo se montan la copia de trabajo y el inicio de sesión del agente elegido. Las conversaciones en curso mantienen su configuración.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Sin acceso a la red, el agente no puede llegar a la API de su modelo, salvo que esa API se ejecute dentro del sandbox. Las instalaciones de paquetes y las solicitudes web también fallan.',
  preparing: 'preparando',
  stopped: 'detenido',
  'A thread can change it before its first message.':
    'Una conversación puede cambiarlo antes de su primer mensaje.',
